      allow get: if d.matches('ok.*');
      allow create: if d.matches('ok.*');
      allow delete: if d.matches('ok.*');
    }
    match /aruma-ref-f5-m3/{d} {
      allow list: if true;
      allow update: if d.matches('ok.*');
    }
    match /aruma-ref-f5-m4/{d} {
      allow get: if request.method == d;
      allow list: if request.method == 'list';
      allow create: if request.method == d;
      allow update: if request.method == d;
      allow delete: if request.method == d;
    }
    match /aruma-ref-f5-m5/{d} {
      allow read: if true;
      allow create: if true;
    }
    match /aruma-ref-f5-m6/{d} {
      allow read: if true;
    }
    match /aruma-ref-f5-m7/{d} {
      allow get: if resource.data.x == 1;
    }
    match /aruma-ref-f5-m8/{d} {
      allow get: if true;
    }
    match /aruma-ref-f5-m9/{d} {
      allow update: if true;
    }
    // request.auth
    match /aruma-ref-f5-a/{d} {
      allow get: if (d == 'authnull' && request.auth == null)
        || (d == 'authnotnull' && request.auth != null)
        || (d == 'uid-a' && request.auth.uid == 'NnwTePTA9BSebOsQJ8DLaKhW11A2')
